  /* ---------- home ---------- */
  "v4.hero.eyebrow": { lv: "Ģimenes darbnīca · Daugavpils, Latvija", en: "Family workshop · Daugavpils, Latvia", ru: "Семейная мастерская · Даугавпилс, Латвия", pl: "Rodzinny warsztat · Dyneburg, Łotwa", uk: "Сімейна майстерня · Даугавпілс, Латвія" },
  "v4.hero.lead": { lv: "Rokām lieti un apstrādāti dekori, sveces un dārza izstrādājumi. Veidoti mūsu ģimenes darbnīcā Daugavpilī.", en: "Hand-cast décor, candles and garden pieces, made and finished in our family workshop in Daugavpils.", ru: "Литой декор, свечи и изделия для сада. Каждую вещь мы изготавливаем и отделываем вручную в нашей семейной мастерской в Даугавпилсе.", pl: "Ręcznie odlewane dekoracje, świece i wyroby ogrodowe, wykonywane w naszej rodzinnej pracowni w Dyneburgu.", uk: "Литий декор, свічки та вироби для саду. Виготовляємо й оздоблюємо вручну в нашій сімейній майстерні в Даугавпілсі." },
  "v4.hero.ctaPieces": { lv: "Apskatīt darbus", en: "See the pieces", ru: "Посмотреть работы", pl: "Zobacz wyroby", uk: "Переглянути роботи" },
