  "v4.hero.alt": { lv: "Ar rokām veidots darbs no Trosheen darbnīcas", en: "A hand-shaped piece from the Trosheen workshop", ru: "Работа ручной работы из мастерской Trosheen", pl: "Ręcznie wykonany wyrób z warsztatu Trosheen", uk: "Виріб ручної роботи з майстерні Trosheen" },
  "v4.letter.eyebrow": { lv: "Par darbnīcu", en: "About the workshop", ru: "О мастерской", pl: "O pracowni", uk: "Про майстерню" },
  "v4.letter.p1": { lv: "Mēs esam Trosheen — neliela ģimenes darbnīca Daugavpilī. Veidojam priekšmetus mājai un dārzam, apvienojot liešanas tehnikas un rūpīgu roku darbu.", en: "We are Trosheen, a small family workshop in Daugavpils. We make objects for the home and garden using casting techniques and careful hand finishing.", ru: "Мы — Trosheen, небольшая семейная мастерская в Даугавпилсе. Создаём декор для дома и сада, сочетая литьё и ручную отделку.", pl: "Jesteśmy Trosheen, małą rodzinną pracownią w Dyneburgu. Tworzymy przedmioty do domu i ogrodu, łącząc techniki odlewania z ręcznym wykończeniem.", uk: "Ми — Trosheen, невелика сімейна майстерня в Даугавпілсі. Створюємо декор для дому та саду, поєднуючи лиття з ручним оздобленням." },
  "v4.letter.p2": { lv: "Katru izstrādājumu apstrādājam, pārbaudām un sagatavojam atsevišķi. Nelielas faktūras un krāsas atšķirības ir daļa no roku darba.", en: "We finish and inspect each piece individually. Small variations in texture and colour are a natural part of the process.", ru: "Каждое изделие отдельно обрабатываем и проверяем. Небольшие отличия фактуры и оттенка — естественная особенность ручной работы.", pl: "Każdy wyrób wykańczamy i sprawdzamy osobno. Niewielkie różnice faktury i koloru są naturalną cechą pracy ręcznej.", uk: "Кожен виріб обробляємо й перевіряємо окремо. Невеликі відмінності фактури та кольору — природна особливість ручної роботи." },
  "v4.letter.signAlt": { lv: "Ar siltām rokām, Oļegs", en: "With warm hands, Olegs", ru: "С тёплыми руками, Олег", pl: "Ciepłymi rękami, Oļegs", uk: "Теплими руками, Олег" },
  "v4.letter.caption1": { lv: "Darbnīcā, kur viss sākas", en: "The workshop where it all begins", ru: "Мастерская, где всё начинается", pl: "Pracownia, w której wszystko się zaczyna", uk: "Майстерня, де все починається" },
  "v4.letter.caption2": { lv: "Pagalmā", en: "In the courtyard", ru: "В нашем дворе", pl: "Na naszym podwórzu", uk: "У нашому дворі" },

  "v4.pillars.eyebrow": { lv: "Mūsu pieeja", en: "Our approach", ru: "Наш подход", pl: "Nasze podejście", uk: "Наш підхід" },
