  "v4.step2.title": { lv: "Liešana", en: "Pouring", ru: "Заливка", pl: "Odlewanie", uk: "Заливання" },
  "v4.step2.desc": { lv: "Sastāvu iepildām veidnē un, ja nepieciešams, pievienojam stiprinājuma elementus.", en: "We cast the material into a mould and add reinforcement where needed.", ru: "Заливаем состав в форму и при необходимости добавляем армирующие элементы.", pl: "Wlewamy masę do formy i w razie potrzeby dodajemy wzmocnienia.", uk: "Заливаємо суміш у форму й за потреби додаємо армувальні елементи." },
  "v4.step3.title": { lv: "Veidošana ar rokām", en: "Shaping by hand", ru: "Ручная формовка", pl: "Ręczne formowanie", uk: "Ручне формування" },
  "v4.step3.desc": { lv: "Pēc izņemšanas no veidnes apstrādājam malas un faktūru.", en: "After demoulding, we refine the edges and surface texture.", ru: "После извлечения из формы обрабатываем кромки и фактуру.", pl: "Po wyjęciu z formy opracowujemy krawędzie i fakturę.", uk: "Після виймання з форми обробляємо краї та фактуру." },
  "v4.step4.title": { lv: "Sacietēšana", en: "Curing", ru: "Набор прочности", pl: "Utwardzanie", uk: "Тверднення" },
  "v4.step4.desc": { lv: "Ļaujam materiālam sacietēt atbilstoši izmantotajam sastāvam.", en: "We allow the material to cure for the time required by its formulation.", ru: "Выдерживаем изделие до набора необходимой прочности.", pl: "Pozwalamy materiałowi utwardzić się zgodnie z wymaganiami mieszanki.", uk: "Даємо матеріалу затвердіти відповідно до складу." },
  "v4.step5.title": { lv: "Krāsa un apdare", en: "Colour and finish", ru: "Окраска и отделка", pl: "Kolor i wykończenie", uk: "Колір і оздоблення" },
  "v4.step5.desc": { lv: "Pievienojam krāsu, apdari un aizsargpārklājumu, ja tas nepieciešams.", en: "We apply colour, finish and protective coating where appropriate.", ru: "Наносим цвет, декоративную отделку и защитное покрытие, если оно предусмотрено.", pl: "Nakładamy kolor, wykończenie i powłokę ochronną, gdy jest potrzebna.", uk: "Наносимо колір, декоративне оздоблення й захисне покриття за потреби." },
