  "v4.band.lead": { lv: "Oļega rokas, vecvecāku prasmes un Alisijas un Nikolasa ziņkārība. Pagalms Daugavpilī, kur gadalaiki skaita laiku labāk par kalendāru.", en: "Olegs' hands, our grandparents' skills and Alisija's and Nikolass' curiosity. A courtyard in Daugavpils where the seasons keep time better than a calendar.", ru: "Руки Олега, опыт бабушек и дедушек, любознательность Алисии и Николаса. Даугавпилсский двор, где времена года считают время лучше календаря.", pl: "Ręce Olegsa, umiejętności dziadków oraz ciekawość Alisiji i Nikolassa. Podwórze w Dyneburgu, gdzie pory roku odmierzają czas lepiej niż kalendarz.", uk: "Руки Олега, досвід бабусь і дідусів, допитливість Алісії та Ніколаса. Двір у Даугавпілсі, де пори року відмірюють час краще за календар." },
  "v4.band.cta": { lv: "Lasīt mūsu stāstu", en: "Read our story", ru: "Читать нашу историю", pl: "Poznaj naszą historię", uk: "Читати нашу історію" },

  "v4.custom.eyebrow": { lv: "Pielāgota darbnīca", en: "Custom workshop", ru: "Мастерская на заказ", pl: "Warsztat na zamówienie", uk: "Майстерня на замовлення" },
  "v4.custom.title": { lv: "Gribat savu, īpašu darbu?", en: "Would you like a piece of your own?", ru: "Хотите что-то особенное?", pl: "Chcesz czegoś wyjątkowego?", uk: "Хочете щось особливе?" },
  "v4.custom.lead": { lv: "Izvēlieties formu, krāsu un nospiedumu — un mēs to izveidosim tieši jums. Dāvanai, dārzam vai atmiņai.", en: "Choose a form, a colour and an impression, and we will make it just for you. For a gift, a garden or a memory.", ru: "Выберите форму, цвет и отпечаток — и мы создадим вещь именно для вас. Для подарка, сада или на память.", pl: "Wybierz formę, kolor i odcisk, a my wykonamy przedmiot specjalnie dla Ciebie. Na prezent, do ogrodu lub na pamiątkę.", uk: "Оберіть форму, колір і відбиток — а ми створимо річ саме для вас. На подарунок, для саду чи на згадку." },
