  "v4.wiz.title": { lv: "Pielāgota darbnīca", en: "Custom workshop", ru: "Мастерская на заказ", pl: "Warsztat na zamówienie", uk: "Майстерня на замовлення" },
  "v4.wiz.lead": { lv: "Izveidojiet darbu kopā ar mums. Jūs izvēlaties — mēs lejam, veidojam un krāsojam ar rokām.", en: "Create a piece together with us. You choose; we cast, shape and paint by hand.", ru: "Создадим вещь вместе. Вы выбираете, а мы отливаем, формируем и красим вручную.", pl: "Stwórzmy coś razem. Ty wybierasz, a my odlewamy, formujemy i malujemy ręcznie.", uk: "Створімо річ разом. Ви обираєте, а ми відливаємо, формуємо й розписуємо вручну." },
  "v4.wiz.fact1": { lv: "Izgatavošana: parasti 2–4 nedēļas", en: "Making time: usually 2–4 weeks", ru: "Срок изготовления: обычно 2–4 недели", pl: "Czas wykonania: zwykle 2–4 tygodnie", uk: "Термін виготовлення: зазвичай 2–4 тижні" },
