function fill(entry: Entry): Record<Lang, string> {
  return {
    lv: entry.lv,
    en: entry.en,
    ru: entry.ru ?? entry.en,
    pl: entry.pl ?? entry.en,
    uk: entry.uk ?? entry.en,
  };
}

export const v4Copy = Object.fromEntries(
  Object.entries(raw).map(([key, entry]) => [key, fill(entry)]),
) as typeof translations;
